<template>
  <div class="page">
    <div class="feedback__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>留言反馈</h3>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="user" label="反馈人" min-width="130" />
            <el-table-column prop="phone" label="联系方式" min-width="150" />
            <el-table-column prop="content" label="反馈内容" min-width="300" />
            <el-table-column prop="tag" label="状态" min-width="110">
              <template #default="scope">
                <el-tag :type="tagType(scope.row.tag)" disable-transitions>{{ scope.row.tag }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="createtime" label="反馈时间" min-width="180" />
            <el-table-column label="操作" min-width="140">
              <template #default="scope">
                <el-button
                  v-if="scope.row.tag === '待处理'"
                  size="small"
                  type="primary"
                  @click="handleView(scope.row)"
                >
                  处理
                </el-button>
                <el-button v-else size="small" @click="handleView(scope.row)">查看</el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="feedback__pagination-wrap">
        <div class="totalnum">
          <h3>反馈统计</h3>
          <p>当前共 {{ tableData.length }} 条反馈</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'

const currentPage = ref(1)
const pageSize = ref(6)

const pagedData = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})

const tagType = (tag) => {
  const map = {
    '待处理': 'danger',
    '处理中': 'warning',
    '已解决': 'success',
  }
  return map[tag] || 'info'
}

const handleView = (row) => {
  ElMessageBox.confirm(`${row.user}：${row.content}`, '处理反馈', {
    confirmButtonText: '标记已解决',
    cancelButtonText: '取消',
  })
    .then(() => {
      row.tag = '已解决'
      ElMessage.success('反馈已标记为已解决')
    })
    .catch(() => {})
}

const tableData = ref([
  {
